import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import "./BuyHouseList.css";

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "₹0.00";
  const v = Number(n);
  if (v <= 0) return "₹0.00";
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function LandDetail() {
  const { id } = useParams();
  const [land, setLand] = useState(null);
  const [err, setErr] = useState("");

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/land/${id}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        setLand(data);
      } catch (e) {
        setErr("Unable to load land details.");
      }
    };
    load();
  }, [id]);

  if (err) return <div className="buy-error">{err}</div>;
  if (!land) return <div className="buy-loading">Loading details...</div>;

  const imgList = Array.isArray(land.images) ? land.images : [];

  return (
    <div className="buy-root" style={{ maxWidth: 1000 }}>
      <Link to="/buy-land" style={{ textDecoration: "none" }}>&larr; Back to list</Link>

      <div className="buy-card" style={{ marginTop: 16 }}>
        <div className="buy-card-left">
          <div className="buy-thumb">
            {imgList.length ? (
              <img
                src={`${process.env.REACT_APP_BACKEND_URL}${imgList[0]}`}
                alt=""
                style={{ width: "100%", height: 180, objectFit: "cover", borderRadius: 12 }}
              />
            ) : (
              <div className="no-img">No Image</div>
            )}
            <span className="badge">Land</span>
          </div>
        </div>

        <div className="buy-card-mid">
          <div className="buy-title">
            {land.zoning || "Land"} in {land.city || land.district || land.state || land.location || ""}
          </div>
          <div className="buy-meta">
            <div className="price">{formatCurrencyINR(land.actualPrice)}</div>
            <div className="meta-item">{(land.area_sqft || 0).toLocaleString()} sq.ft</div>
            {land.zoning && <div className="meta-item">{land.zoning}</div>}
          </div>

          <div style={{ marginTop: 10, color: "#334155", lineHeight: 1.6 }}>
            <div><strong>Location:</strong> {land.location || "-"}</div>
            <div><strong>State:</strong> {land.state || "-"}</div>
            <div><strong>District:</strong> {land.district || "-"}</div>
            <div><strong>City:</strong> {land.city || "-"}</div>
            <div><strong>Latitude:</strong> {land.latitude ?? "-"}</div>
            <div><strong>Longitude:</strong> {land.longitude ?? "-"}</div>
            <div><strong>Contact:</strong> {land.contact || "-"}</div>
          </div>
        </div>

        <div className="buy-card-right">
          <div className="btn-row">
            <a
              className="btn contact"
              href={land.contact ? `tel:${land.contact}` : undefined}
              onClick={(e) => !land.contact && e.preventDefault()}
            >
              Call
            </a>
          </div>
        </div>
      </div>

      {imgList.length > 1 && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 12, marginTop: 16 }}>
          {imgList.slice(1).map((src) => (
            <img
              key={src}
              src={`${process.env.REACT_APP_BACKEND_URL}${src}`}
              alt=""
              style={{ width: "100%", height: 160, objectFit: "cover", borderRadius: 12 }}
            />
          ))}
        </div>
      )}
    </div>
  );
}
